import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CHX4lV2z.js";const n="/LightRSI/images/context-cleaner.gif",g=JSON.parse('{"title":"Context Cleaner","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/context-cleaner.md","filePath":"user-guide/context-cleaner.md","lastUpdated":1789811186000}'),l={name:"user-guide/context-cleaner.md"};function o(d,e,r,c,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="context-cleaner" tabindex="-1">Context Cleaner <a class="header-anchor" href="#context-cleaner" aria-label="Permalink to &quot;Context Cleaner&quot;">​</a></h1><p>Context Cleaner is LightRSI&#39;s product for reviewing and cleaning a session&#39;s context <strong>by task</strong>. It shows task descriptions, context usage, recommendations, and protected content so you can choose which eligible tasks to remove from the context carried forward to the model.</p><p>In the project structure, LightRSI is the runtime and platform, TokenPilot is a context-management preset, and Cleaner is a user-facing product. Cleaner entrypoints are supplied through the shared CLI, MCP, and host integrations described below.</p><p>Analysis does not rewrite context. Cleaning requires your explicit task selection. Recommendations do not select tasks for you, and protected tasks cannot be selected.</p><details><summary>Watch the Codex task-selection demo (GIF, approximately 3 MB)</summary><img src="'+n+`" alt="Codex Context Cleaner task selection" loading="lazy" decoding="async" width="2000" height="1629"></details><h2 id="cleaner-reduction-and-automatic-eviction" tabindex="-1">Cleaner, Reduction, and Automatic Eviction <a class="header-anchor" href="#cleaner-reduction-and-automatic-eviction" aria-label="Permalink to &quot;Cleaner, Reduction, and Automatic Eviction&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Capability</th><th style="text-align:left;">How it is used</th></tr></thead><tbody><tr><td style="text-align:left;">Context Cleaner</td><td style="text-align:left;">You inspect a plan, choose eligible tasks, and approve a specific clean</td></tr><tr><td style="text-align:left;">Context Reduction</td><td style="text-align:left;">Runtime policies trim oversized or noisy payloads</td></tr><tr><td style="text-align:left;">Automatic Context Eviction</td><td style="text-align:left;">Host runtime policies decide when eligible older context can be evicted</td></tr></tbody></table><p>Cleaner reuses task lifecycle and host rewrite capabilities. It is not a command to rerun reduction, and selecting tasks is not the same as enabling an automatic eviction mode.</p><h2 id="supported-hosts" tabindex="-1">Supported Hosts <a class="header-anchor" href="#supported-hosts" aria-label="Permalink to &quot;Supported Hosts&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Host</th><th style="text-align:left;">User entry point</th><th style="text-align:left;">When an approved clean takes effect</th></tr></thead><tbody><tr><td style="text-align:left;">OpenClaw</td><td style="text-align:left;"><code>/lightrsi clean</code> or <code>lightrsi openclaw clean --session &lt;session-id&gt;</code></td><td style="text-align:left;">A successful explicit apply returns <code>applied</code> immediately</td></tr><tr><td style="text-align:left;">Codex</td><td style="text-align:left;"><code>!lightrsi-clean</code> for the terminal selector; the installed <code>lightrsi-clean</code> skill for the MCP form; or <code>lightrsi codex clean</code></td><td style="text-align:left;">Selection is scheduled for the next eligible host request</td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;">Installed <code>lightrsi-clean</code> analysis skill or <code>lightrsi claude-code clean</code></td><td style="text-align:left;">Selection is scheduled for the next eligible host request</td></tr><tr><td style="text-align:left;">DeepSeek Harness</td><td style="text-align:left;">No public Cleaner command is wired into the current adapter entrypoint</td><td style="text-align:left;">Its automatic eviction and <code>/tokenpilot-status</code> are separate features</td></tr></tbody></table><p>For OpenClaw, Codex, and Claude Code, the shared terminal CLI supports analysis, explicit selection, status, and cancellation. The host-specific interfaces differ as described below.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Run these commands from a LightRSI checkout after installing workspace dependencies with <code>corepack pnpm install</code>:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-T8l6f" id="tab-Ad25WxA" checked><label data-title="OpenClaw" for="tab-Ad25WxA">OpenClaw</label><input type="radio" name="group-T8l6f" id="tab-16N0w3m"><label data-title="Codex" for="tab-16N0w3m">Codex</label><input type="radio" name="group-T8l6f" id="tab-geo3RBI"><label data-title="Claude Code" for="tab-geo3RBI">Claude Code</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Shared CLI, if you want to use the terminal commands</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lightrsi:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lightrsi:install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Native OpenClaw plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> component:install:tokenpilot:openclaw</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cleaner:install:codex</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cleaner:install:claude-code</span></span></code></pre></div></div></div><p>The Codex and Claude Code installers build the shared CLI, recovery MCP, and selected adapter, then install the Cleaner command skills. Codex also registers the Cleaner MCP server used for its task-selection form. DeepSeek Harness has no equivalent public Cleaner installer in this workflow.</p><p>For the OpenClaw shared CLI, use a Bash environment and ensure <code>~/.local/bin</code> (or your <code>LIGHTRSI_BIN_DIR</code>) is on <code>PATH</code>. Codex and Claude Code installers use <code>~/.local/bin</code> by default on Linux/macOS; on Windows they create command launchers and use the npm command directory when it is already on <code>PATH</code>.</p><p>Start a session through the installed adapter so Cleaner has session context to inspect. See <a href="/LightRSI/getting-started/install-first-plugin">Install Your First Plugin</a> for host setup and custom configuration paths. Cleaner also needs task lifecycle information to identify eligible tasks; installation alone does not guarantee selectable tasks.</p><h3 id="task-classification-and-recommendations" tabindex="-1">Task Classification and Recommendations <a class="header-anchor" href="#task-classification-and-recommendations" aria-label="Permalink to &quot;Task Classification and Recommendations&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Entry point</th><th style="text-align:left;">Source of task information and recommendations</th></tr></thead><tbody><tr><td style="text-align:left;">OpenClaw native <code>/lightrsi clean</code></td><td style="text-align:left;">Host-managed model completion for pending task classification and recommendations; explicitly configured estimator fallback on older hosts</td></tr><tr><td style="text-align:left;">OpenClaw standalone CLI</td><td style="text-align:left;">Existing task registry plus the configured <code>taskStateEstimator</code> recommendation provider</td></tr><tr><td style="text-align:left;">Codex</td><td style="text-align:left;">Task registry, with estimator-backed refresh during Cleaner analysis; recommendations use the resolved estimator connection</td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;">Task registry populated on the gateway request path; Cleaner recommendations use <code>taskStateEstimator</code> settings</td></tr></tbody></table><p>For Codex and Claude Code, the explicit estimator configuration is in <code>~/.codex/tokenpilot.json</code> or <code>~/.claude/tokenpilot.json</code> respectively (or your configured alternative path). Merge this block into the existing configuration, replacing the connection placeholders:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;taskStateEstimator&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;baseUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://your-estimator-endpoint/v1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;apiKey&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_ESTIMATOR_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-estimator-model&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use local configuration for credentials, not a checked-in file. This provides model access for task evidence and recommendations; user approval is still required for Cleaner. In Claude Code, task classification runs on ordinary gateway requests, so analyze after the session has produced task lifecycle evidence. A missing provider or incomplete task evidence must not be worked around by selecting protected tasks.</p><h2 id="_1-analyze-the-intended-session" tabindex="-1">1. Analyze the Intended Session <a class="header-anchor" href="#_1-analyze-the-intended-session" aria-label="Permalink to &quot;1. Analyze the Intended Session&quot;">​</a></h2><p>Run the command for your host:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-dCO9K" id="tab-Jlp-KGc" checked><label data-title="OpenClaw" for="tab-Jlp-KGc">OpenClaw</label><input type="radio" name="group-dCO9K" id="tab--o1lF7g"><label data-title="Codex" for="tab--o1lF7g">Codex</label><input type="radio" name="group-dCO9K" id="tab-1PpDVDH"><label data-title="Claude Code" for="tab-1PpDVDH">Claude Code</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openclaw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --session</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">session-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div></div></div><p>Replace placeholders with actual IDs. Use <code>--session &lt;session-id&gt;</code> with any of these hosts to target a specific session. Without an explicit ID, the CLI resolves a session from its host context; check the displayed <strong>Host/session</strong> before approving anything. Do not assume it is the conversation you intended when several sessions exist.</p><p>Analysis stores a plan and a receipt, and may use model-assisted task classification or recommendations, but does not apply a context rewrite. In an interactive terminal it then opens the task selector. Without a TTY it prints the plan, selectable task IDs, and an explicit apply-command hint without scheduling a clean.</p><h2 id="_2-review-and-select-tasks" tabindex="-1">2. Review and Select Tasks <a class="header-anchor" href="#_2-review-and-select-tasks" aria-label="Permalink to &quot;2. Review and Select Tasks&quot;">​</a></h2><p>The plan includes its ID, host/session, context usage, protected and unassigned context, task descriptions, size, recommendations, and reason codes.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Plan field</th><th style="text-align:left;">How to read it</th></tr></thead><tbody><tr><td style="text-align:left;"><code>clean</code></td><td style="text-align:left;">Recommended for cleaning, subject to selectability and your approval</td></tr><tr><td style="text-align:left;"><code>keep</code></td><td style="text-align:left;">Recommended to retain; review the reason and whether it is selectable</td></tr><tr><td style="text-align:left;"><code>protected</code> / <code>[-]</code></td><td style="text-align:left;">Cannot be selected</td></tr><tr><td style="text-align:left;"><code>[ ]</code> / <code>[x]</code></td><td style="text-align:left;">Unselected / selected task in the terminal selector</td></tr><tr><td style="text-align:left;"><code>exact</code>, <code>estimated</code>, <code>chars_only</code></td><td style="text-align:left;">Accounting mode; character counts are not token counts</td></tr></tbody></table><p>Current OpenClaw and Claude Code Cleaner snapshots use character counts. Codex uses precise tokenizer counts when available and otherwise falls back to characters. A dash in the share column is not zero usage, and a context-window percentage is shown only when the required token and window data are available.</p><p>For the raw terminal selector, <strong>Up/Down</strong> moves between selectable tasks, <strong>Space</strong> toggles a task, and <strong>Enter submits the checked selection</strong>. Tasks start unchecked. <code>q</code> or Escape cancels; Ctrl+C interrupts and cancels the plan. Submitting no selected tasks applies no change. These keys describe the terminal selector, not a host-rendered MCP form.</p><p>To approve a plan explicitly, copy the complete plan and task IDs from the analysis:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plan</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">plan-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --select</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">task-id-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">1&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">task-id-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">2&gt;</span></span></code></pre></div><p>Here <code>&lt;host&gt;</code> is <code>openclaw</code>, <code>codex</code>, or <code>claude-code</code>. This command is the approval itself; it does not open another task-selection prompt. Use task IDs from selectable rows, not task labels, row numbers, or a shortened session ID.</p><h2 id="_3-check-the-result" tabindex="-1">3. Check the Result <a class="header-anchor" href="#_3-check-the-result" aria-label="Permalink to &quot;3. Check the Result&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">plan-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Receipt status</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>analyzed</code></td><td style="text-align:left;">A plan exists; no selection has been approved</td></tr><tr><td style="text-align:left;"><code>approved</code></td><td style="text-align:left;">The selected tasks have been approved; this alone is not proof of application</td></tr><tr><td style="text-align:left;"><code>scheduled</code></td><td style="text-align:left;">Waiting for the host to execute the approved clean</td></tr><tr><td style="text-align:left;"><code>applied</code></td><td style="text-align:left;">The host has recorded application evidence</td></tr><tr><td style="text-align:left;"><code>stale</code></td><td style="text-align:left;">The plan no longer passes validation; analyze again and review a new selection</td></tr><tr><td style="text-align:left;"><code>cancelled</code></td><td style="text-align:left;">The plan has been cancelled</td></tr><tr><td style="text-align:left;"><code>failed</code></td><td style="text-align:left;">The clean failed; inspect its reasons and fallback information</td></tr></tbody></table><p>For Codex and Claude Code, a <code>scheduled</code> receipt is expected immediately after approval. Resume the same session with a normal follow-up request, then check the receipt again. The request used to submit the selection is not itself proof that the clean has been applied. OpenClaw&#39;s successful explicit apply returns an <code>applied</code> receipt immediately.</p><p>Keep <strong>estimated</strong>, <strong>scheduled</strong>, and <strong>applied</strong> savings separate. A plan estimate or pending schedule does not establish that context was removed, and Cleaner context-size accounting is not a measurement of provider billing savings.</p><h2 id="cancel-a-pending-plan" tabindex="-1">Cancel a Pending Plan <a class="header-anchor" href="#cancel-a-pending-plan" aria-label="Permalink to &quot;Cancel a Pending Plan&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lightrsi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cancel</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">plan-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Read the returned receipt: cancellation is not an undo command for an already applied clean. If execution has already completed, cancelling cannot restore the prior context. Analysis, selection, status, and cancellation always refer to a specific plan; status and cancellation do not rerun analysis.</p><h2 id="host-specific-interfaces" tabindex="-1">Host-Specific Interfaces <a class="header-anchor" href="#host-specific-interfaces" aria-label="Permalink to &quot;Host-Specific Interfaces&quot;">​</a></h2><h3 id="openclaw" tabindex="-1">OpenClaw <a class="header-anchor" href="#openclaw" aria-label="Permalink to &quot;OpenClaw&quot;">​</a></h3><p>Inside an OpenClaw conversation:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lightrsi clean</span></span>
<span class="line"><span>/lightrsi clean --session &lt;session-id&gt;</span></span>
<span class="line"><span>/lightrsi clean --plan &lt;plan-id&gt; --select &lt;task-id-1&gt;,&lt;task-id-2&gt;</span></span>
<span class="line"><span>/lightrsi clean --status &lt;plan-id&gt;</span></span>
<span class="line"><span>/lightrsi clean --cancel &lt;plan-id&gt;</span></span></code></pre></div><p>The first command analyzes the mapped current session; provide a session ID if no mapping is available. The native analysis command does not apply a rewrite. <code>/tokenpilot clean</code> and <code>/tp clean</code> are aliases.</p><p>The native command can classify pending turns and generate recommendations through OpenClaw&#39;s host-managed model completion service. Older hosts without that service fall back to explicitly configured <code>taskStateEstimator</code> settings. Do not assume the standalone terminal entrypoint has the same host-managed model access. OpenClaw&#39;s canonical eviction backend archives task content before committing the rewrite, which replaces the selected content with a pointer stub or drops it according to the replacement mode. This archive does not make Cleaner cancellation an undo operation.</p><h3 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to &quot;Codex&quot;">​</a></h3><p>For the terminal selector, type the shell escape yourself inside Codex:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!lightrsi-clean</span></span></code></pre></div><p>The equivalent standalone launcher is <code>lightrsi-clean</code>; the explicit host CLI is <code>lightrsi codex clean</code>. On Windows, the terminal selector uses the current terminal&#39;s modal console buffer and restores it on exit.</p><p>For the host-rendered form, explicitly invoke the installed <code>lightrsi-clean</code> skill (documented as <code>$lightrsi-clean</code> in the Codex adapter README). It calls the Cleaner MCP tool, which analyzes and collects the user&#39;s selection in one invocation. The host owns the form&#39;s controls. Protected tasks appear in the plan text but are not selectable form fields. Cancelling or accepting an empty selection schedules nothing.</p><p>Both paths schedule an accepted selection for a later host request, where Codex performs a response-chain rebase. The explicit <code>lightrsi-clean-status</code>, <code>lightrsi-clean-apply</code>, and <code>lightrsi-clean-cancel</code> skills require the complete plan ID; apply also requires the complete selected task IDs supplied by the user.</p><h3 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h3><p>The installed <code>lightrsi-clean</code> skill performs <strong>analysis only</strong>. It must not select tasks, confirm a prompt, or run the apply command for you. Review the output, then personally supply the plan and task IDs for the explicit apply flow, or use <code>lightrsi claude-code clean</code> in an interactive terminal.</p><p>The shared installer also provides the explicit status, apply, and cancel skills. These require the complete plan ID, and apply requires the exact task IDs you choose. An accepted selection is scheduled; the gateway applies an archived request overlay on a subsequent eligible request and records the result. This does not promise an immediate change to the currently running request.</p><h3 id="deepseek-harness" tabindex="-1">DeepSeek Harness <a class="header-anchor" href="#deepseek-harness" aria-label="Permalink to &quot;DeepSeek Harness&quot;">​</a></h3><p>The repository contains Cleaner backend modules for Harness, but its current Cordis entrypoint and command registration do not expose a public Cleaner workflow. Do not use <code>lightrsi deepseek-harness clean</code> or assume <code>/tokenpilot-status</code> can analyze, approve, or cancel Cleaner plans. See <a href="/LightRSI/hosts/deepseek-harness">DeepSeek Harness</a> for its implemented automatic eviction and status workflow.</p><h2 id="protected-context-and-recommendations" tabindex="-1">Protected Context and Recommendations <a class="header-anchor" href="#protected-context-and-recommendations" aria-label="Permalink to &quot;Protected Context and Recommendations&quot;">​</a></h2><p>Cleaner protects system/developer instructions, current or active work, unresolved tasks, ambiguous task attribution, and unsafe tool-call/result relationships. Application also depends on the host&#39;s archive and rewrite checks. Targets are revalidated against current host context before application; approval does not bypass those checks.</p><p>Task descriptions and recommendations help you understand the plan. They do not choose arbitrary text ranges, override safety checks, or authorize a clean. If the recommendation provider is unavailable or fails, the shared fallback keeps deterministic accounting and conservative keep/protected recommendations instead of inventing a selection. Missing task lifecycle evidence can leave no selectable tasks.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Symptom</th><th style="text-align:left;">What to do</th></tr></thead><tbody><tr><td style="text-align:left;">No session or snapshot is available</td><td style="text-align:left;">Start a session through the installed adapter, verify the host/session shown, and pass <code>--session</code> when needed</td></tr><tr><td style="text-align:left;">Everything is protected or unassigned</td><td style="text-align:left;">Check task lifecycle information and host estimator setup; active or uncertain tasks must remain protected</td></tr><tr><td style="text-align:left;">No interactive selector</td><td style="text-align:left;">A non-TTY invocation is analysis-only. Use a real terminal, the supported Codex MCP form, or the explicit plan/selection command</td></tr><tr><td style="text-align:left;">Plan is <code>stale</code></td><td style="text-align:left;">Analyze the current session again and review the new plan; do not reuse old task IDs without checking</td></tr><tr><td style="text-align:left;">Receipt stays <code>scheduled</code></td><td style="text-align:left;">Continue the same Codex/Claude Code session, then query the receipt; inspect reasons if application is deferred</td></tr><tr><td style="text-align:left;">Counts are in characters</td><td style="text-align:left;">The snapshot has no supported precise token counts; do not interpret characters as tokens</td></tr><tr><td style="text-align:left;">Codex form is unavailable</td><td style="text-align:left;">Check <code>lightrsi codex doctor</code>; recovery MCP and Cleaner MCP health are reported separately. The terminal selector is a separate entrypoint</td></tr><tr><td style="text-align:left;">Claude Code skill only prints analysis</td><td style="text-align:left;">This is intentional. Task selection and approval require your explicit action</td></tr></tbody></table><h2 id="implementation-references" tabindex="-1">Implementation References <a class="header-anchor" href="#implementation-references" aria-label="Permalink to &quot;Implementation References&quot;">​</a></h2><ul><li><a href="https://github.com/zjunlp/LightRSI/blob/main/README.md#products" target="_blank" rel="noreferrer">Project README</a> — product and installation entrypoints</li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/openclaw/README.md" target="_blank" rel="noreferrer">OpenClaw adapter</a> and <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/codex/README.md#cleaner-selection-in-codex" target="_blank" rel="noreferrer">Codex adapter</a> — native interfaces</li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/products/cli/src/clean.ts" target="_blank" rel="noreferrer">Shared CLI controller</a> and <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/shared/command-skill-bridge.ts" target="_blank" rel="noreferrer">command skills</a> — selection, approval, and command behavior</li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/packages/features/cleaner/src/contracts.ts" target="_blank" rel="noreferrer">Cleaner contracts</a> — accounting and receipt states</li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/codex/src/context-cleaner/control-service.ts" target="_blank" rel="noreferrer">Codex control service</a> and <a href="https://github.com/zjunlp/LightRSI/blob/main/components/adapters/claude-code/src/context-cleaner/control-service.ts" target="_blank" rel="noreferrer">Claude Code control service</a> — estimator and recommendation configuration</li></ul>`,67)])])}const u=t(l,[["render",o]]);export{g as __pageData,u as default};
